export function flipTransform(side: "top" | "bottom" | "left" | "right") {
  const rotate =
    side === "top"
      ? "rotateX(-20deg)"
      : side === "bottom"
        ? "rotateX(20deg)"
        : side === "left"
          ? "rotateY(20deg)"
          : "rotateY(-20deg)";
  return `perspective(500px) ${rotate} scale(0.8)`;
}

export function uprightTransform(side: "top" | "bottom" | "left" | "right") {
  const rotate = side === "left" || side === "right" ? "rotateY(0deg)" : "rotateX(0deg)";
  return `perspective(500px) ${rotate} scale(1)`;
}

"use client";

import * as React from "react";
import {
  animate,
  useMotionValue,
  useMotionValueEvent,
  type Transition,
} from "motion/react";
import { cn } from "@/lib/utils";
import {
  srOnlyStyle,
  useReduceMotion,
  useSeen,
  useTempoTransition,
} from "./motion";

type Format = {
  decimals: number;
  decimalSeparator: string;
  thousandSeparator?: string;
  padLength: number;
};

function formatNumber(value: number, options: Format) {
  const { decimals, decimalSeparator, thousandSeparator, padLength } = options;
  const fixed = Math.abs(value).toFixed(decimals);
  const sign = value < 0 && Number(fixed) !== 0 ? "-" : "";
  const [integer = "0", fraction] = fixed.split(".");
  const padded = integer.padStart(padLength, "0");
  const grouped =
    thousandSeparator === undefined
      ? padded
      : padded.replace(/\B(?=(\d{3})+$)/g, thousandSeparator);
  return fraction
    ? `${sign}${grouped}${decimalSeparator}${fraction}`
    : `${sign}${grouped}`;
}

const countSpring: Transition = {
  type: "spring",
  stiffness: 90,
  damping: 50,
  restDelta: 0.001,
  restSpeed: 0.01,
};

export type CountingNumberProps = Omit<React.ComponentProps<"span">, "children"> & {
  number: number;
  fromNumber?: number;
  padStart?: boolean;
  decimalPlaces?: number;
  decimalSeparator?: string;
  thousandSeparator?: string;
  inView?: boolean;
  inViewOnce?: boolean;
  delay?: number;
  initiallyStable?: boolean;
  transition?: Transition;
  onCompleted?: () => void;
};

export function CountingNumber({
  number,
  fromNumber = 0,
  padStart = false,
  decimalPlaces = 0,
  decimalSeparator = ".",
  thousandSeparator,
  inView = false,
  inViewOnce = true,
  delay = 0,
  initiallyStable = false,
  transition,
  onCompleted,
  className,
  ...props
}: CountingNumberProps) {
  const ref = React.useRef<HTMLSpanElement>(null);
  const visualRef = React.useRef<HTMLSpanElement>(null);
  const seen = useSeen(ref, inView, inViewOnce);
  const reduce = useReduceMotion();
  const spring = useTempoTransition(transition ?? countSpring);
  const value = useMotionValue(initiallyStable ? number : fromNumber);

  const format = React.useMemo<Format>(
    () => ({
      decimals: decimalPlaces,
      decimalSeparator,
      thousandSeparator,
      padLength: padStart ? Math.floor(Math.abs(number)).toString().length : 0,
    }),
    [decimalPlaces, decimalSeparator, number, padStart, thousandSeparator],
  );

  const write = React.useCallback(
    (latest: number) => {
      const node = visualRef.current;
      if (node) node.textContent = formatNumber(latest, format);
    },
    [format],
  );

  useMotionValueEvent(value, "change", write);

  React.useLayoutEffect(() => {
    write(value.get());
  }, [write, value]);

  const springRef = React.useRef(spring);
  React.useEffect(() => {
    springRef.current = spring;
  }, [spring]);

  React.useEffect(() => {
    if (!seen) return;
    if (reduce) {
      value.jump(number);
      onCompleted?.();
      return;
    }
    let controls: ReturnType<typeof animate> | undefined;
    const timer = window.setTimeout(() => {
      controls = animate(value, number, {
        ...springRef.current,
        onComplete: onCompleted,
      } as Transition);
    }, delay);
    return () => {
      window.clearTimeout(timer);
      controls?.stop();
    };
  }, [delay, number, onCompleted, reduce, seen, value]);

  React.useEffect(() => () => value.stop(), [value]);

  const finalText = formatNumber(number, format);

  return (
    <span
      ref={ref}
      data-slot="counting-number"
      className={cn("inline-block tabular-nums", className)}
      {...props}
    >
      <span aria-hidden="true" ref={visualRef} />
      <span className="sr-only" style={srOnlyStyle()}>
        {finalText}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";
import { motion, type Transition } from "motion/react";
import { cn } from "@/lib/utils";
import { CountingNumber } from "./counting-number";
import { useReduceMotion, useSeen } from "./motion";

const arcSpring: Transition = {
  type: "spring",
  stiffness: 90,
  damping: 50,
  restDelta: 0.001,
};

const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));

export type RadialProgressProps = React.ComponentProps<"div"> & {
  value: number;
  size?: number;
  strokeWidth?: number;
  from?: number;
  label?: string;
  showLabel?: boolean;
  showTicks?: boolean;
  ticks?: number;
  inView?: boolean;
  color?: string;
  trackColor?: string;
  transition?: Transition;
};

export function RadialProgress({
  value,
  size = 148,
  strokeWidth = 10,
  from = 0,
  label,
  showLabel = true,
  showTicks = true,
  ticks = 48,
  inView = true,
  color = "currentColor",
  trackColor = "currentColor",
  transition,
  className,
  style,
  ...props
}: RadialProgressProps) {
  const ref = React.useRef<HTMLDivElement>(null);
  const seen = useSeen(ref, inView, true);
  const reduce = useReduceMotion();
  const id = React.useId().replace(/:/g, "");
  const safe = clamp(value, 0, 100);
  const radius = (size - strokeWidth) / 2;
  const center = size / 2;
  const spring = reduce ? { duration: 0 } : transition ?? arcSpring;
  const tickCount = Math.max(4, Math.round(ticks));

  return (
    <div
      ref={ref}
      data-slot="radial-progress"
      role="progressbar"
      aria-valuemin={0}
      aria-valuemax={100}
      aria-valuenow={Math.round(safe)}
      aria-label={label ?? "Progress"}
      className={cn("relative inline-flex items-center justify-center", className)}
      style={{ width: size, height: size, ...style }}
      {...props}
    >
      <svg
        width={size}
        height={size}
        viewBox={`0 0 ${size} ${size}`}
        className="-rotate-90"
        aria-hidden="true"
      >
        <defs>
          <linearGradient id={`radial-${id}`} x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor={color} stopOpacity="0.55" />
            <stop offset="100%" stopColor={color} stopOpacity="1" />
          </linearGradient>
        </defs>
        <circle
          cx={center}
          cy={center}
          r={radius}
          fill="none"
          stroke={trackColor}
          strokeOpacity="0.12"
          strokeWidth={strokeWidth}
          strokeLinecap="round"
        />
        <motion.circle
          cx={center}
          cy={center}
          r={radius}
          fill="none"
          stroke={`url(#radial-${id})`}
          strokeWidth={strokeWidth}
          strokeLinecap="round"
          initial={{ pathLength: 0 }}
          animate={{ pathLength: seen ? safe / 100 : 0 }}
          transition={spring}
        />
        {showTicks
          ? Array.from({ length: tickCount }, (_, index) => {
              const angle = (index / tickCount) * 360;
              const major = index % 6 === 0;
              const active = (index / tickCount) * 100 <= safe;
              const inner = radius + strokeWidth / 2 + 4;
              const outer = inner + (major ? 5 : 2.5);
              return (
                <line
                  key={index}
                  x1={center}
                  y1={center - inner}
                  x2={center}
                  y2={center - outer}
                  stroke={color}
                  strokeOpacity={active ? 0.5 : 0.14}
                  strokeWidth={major ? 1.4 : 1}
                  strokeLinecap="round"
                  transform={`rotate(${angle} ${center} ${center})`}
                />
              );
            })
          : null}
      </svg>
      <div className="absolute inset-0 flex flex-col items-center justify-center gap-1 text-center">
        <CountingNumber
          number={safe}
          fromNumber={from}
          inView={inView}
          thousandSeparator=","
          className="font-medium leading-none tracking-[-0.04em] tabular-nums"
          style={{ fontSize: Math.max(22, Math.round(size * 0.25)) }}
        />
        {showLabel ? (
          <span className="text-[13px] leading-4 text-muted-foreground">
            {label ?? "complete"}
          </span>
        ) : null}
      </div>
    </div>
  );
}

"use client";

import { useReducedMotion } from "motion/react";
import { useSyncExternalStore } from "react";

const subscribe = () => () => {};

export function useHydratedReducedMotion() {
  const reduce = useReducedMotion() ?? false;
  const mounted = useSyncExternalStore(
    subscribe,
    () => true,
    () => false,
  );
  return mounted ? reduce : false;
}
